script:
(function () {
  'use strict';
  // Return on investment.
  //   cost = amount invested + fees;  received = amount returned + income kept
  //   ROI = (received - cost) / cost
  //   annualized ROI = (received / cost)^(1 / years) - 1   (compound annual growth rate)
  // With dates, years = days between the dates / 365.25.
  // Checked in Node (roi.test.js): $10,000 -> $14,500 over 3 years = 45% total and 13.19% a year
  // (1.45^(1/3) = 1.13185); $1,000 -> $2,000 over 2.5 years = 100% and 31.95% (2^(1/2.5) = 1.31951);
  // doubling in 10 years = 7.177% a year (rule-of-72 cross-check); a loss to $0 = -100%; 2020-01-01
  // to 2025-01-01 = 1,827 days = 5.002 years; the steady-return table ends exactly at the received total.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var OUTPUTS = ['roiTotal', 'roiAnnual', 'roiGain', 'roiCost', 'roiReceived', 'roiPeriod', 'roiMultiple'];

  // --- calc start
  function roi(p) {
    var cost = p.invested + p.costs, received = p.returned + p.income;
    var total = (received - cost) / cost;
    var annual = received <= 0 ? -1 : Math.pow(received / cost, 1 / p.years) - 1;
    return { cost: cost, received: received, gain: received - cost, total: total, annual: annual, multiple: received / cost };
  }

  // Whole days between two yyyy-mm-dd strings, ignoring time zones; null if either is invalid.
  function daysBetween(from, to) {
    var a = /^(\d{4})-(\d{2})-(\d{2})$/.exec(from || ''), b = /^(\d{4})-(\d{2})-(\d{2})$/.exec(to || '');
    if (!a || !b) return null;
    return Math.round((Date.UTC(+b[1], +b[2] - 1, +b[3]) - Date.UTC(+a[1], +a[2] - 1, +a[3])) / 86400000);
  }

  function steadyPath(cost, annual, years) {
    var rows = [], prev = cost, full = Math.floor(years + 1e-9);
    for (var y = 1; y <= full; y++) {
      var v = cost * Math.pow(1 + annual, y);
      rows.push({ year: String(y), gain: v - prev, value: v, roi: v / cost - 1 });
      prev = v;
    }
    if (years - full > 1e-6) {
      var last = cost * Math.pow(1 + annual, years);
      rows.push({ year: (Math.round(years * 100) / 100) + ' (end)', gain: last - prev, value: last, roi: last / cost - 1 });
    }
    return rows;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) { return (x * 100).toLocaleString('en-US', { maximumFractionDigits: 2 }) + '%'; }

  function iso(d) { return d.toISOString().slice(0, 10); }

  function fail(msg) {
    var error = document.getElementById('roiError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('roiPath').innerHTML = '';
    document.getElementById('roiNote').hidden = true;
  }

  function update() {
    var byDates = document.getElementById('roiTimeMode').value === 'dates';
    document.getElementById('roiLengthFields').hidden = byDates;
    document.getElementById('roiDateFields').hidden = !byDates;
    document.getElementById('roiError').hidden = true;
    var invested = num('roiInvested'), returned = num('roiReturned'), income = num('roiIncome'), costs = num('roiCosts');
    if ([invested, returned, income, costs].some(isNaN)) return fail('Enter a number in each amount box (0 is fine for the optional ones).');
    if (invested < 0 || returned < 0 || income < 0 || costs < 0) return fail('Amounts cannot be negative.');
    if (invested + costs <= 0) return fail('Enter an amount invested above $0.');
    var years, period;
    if (byDates) {
      var days = daysBetween(document.getElementById('roiFrom').value, document.getElementById('roiTo').value);
      if (days === null) return fail('Choose both dates.');
      if (days <= 0) return fail('The end date must be after the start date.');
      years = days / 365.25;
      period = days.toLocaleString('en-US') + (days === 1 ? ' day' : ' days') + ' (' + years.toFixed(2) + ' years)';
    } else {
      var y = num('roiYears'), m = num('roiMonths');
      if (isNaN(y) || isNaN(m) || y < 0 || m < 0 || y > 100 || m > 11 || y + m / 12 <= 0) return fail('Enter 0 to 100 years and 0 to 11 months, with a total above zero.');
      years = y + m / 12;
      period = years.toFixed(2).replace(/\.00$/, '') + (years === 1 ? ' year' : ' years');
    }
    var r = roi({ invested: invested, returned: returned, income: income, costs: costs, years: years });
    if (!isFinite(r.annual) || r.annual > 1e6) return fail('The annualized figure is too large to show. Check the amounts and the holding period.');
    document.getElementById('roiTotal').textContent = pct(r.total);
    document.getElementById('roiAnnual').textContent = pct(r.annual);
    document.getElementById('roiGainLabel').textContent = r.gain < 0 ? 'Net loss' : 'Net gain';
    document.getElementById('roiGain').textContent = money.format(Math.abs(r.gain));
    document.getElementById('roiCost').textContent = money.format(r.cost);
    document.getElementById('roiReceived').textContent = money.format(r.received);
    document.getElementById('roiPeriod').textContent = period;
    document.getElementById('roiMultiple').textContent = r.multiple.toFixed(3).replace(/\.?0+$/, '') + '×';
    var note = document.getElementById('roiNote');
    note.hidden = years >= 1;
    note.textContent = 'The holding period is under a year, so the annualized ROI assumes the same pace would continue for a full year. Treat it with care.';
    document.getElementById('roiPath').innerHTML = years > 100 ? '' : steadyPath(r.cost, r.annual, years).map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.gain) + '</td><td>' +
             money.format(row.value) + '</td><td>' + pct(row.roi) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('roiForm');
    var to = new Date(), from = new Date(to.getTime());
    from.setFullYear(to.getFullYear() - 3);
    if (!document.getElementById('roiFrom').value) document.getElementById('roiFrom').value = iso(from);
    if (!document.getElementById('roiTo').value) document.getElementById('roiTo').value = iso(to);
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
